import routeData from './routes.json'

// Sea routes between every pair of ports, generated by scripts/buildRoutes.ts.

export interface Route {
  from: string
  to: string
  /** Sea distance, nautical miles. */
  nm: number
  /** Canal ids passed on the way. */
  canals: string[]
  /** [lon, lat] points from `from` to `to`. */
  path: [number, number][]
}

type Raw = Record<string, { nm: number; canals: string[]; path: [number, number][] }>
const RAW = routeData as unknown as Raw
const cache = new Map<string, Route>()

export function getRoute(from: string, to: string): Route {
  const key = `${from}>${to}`
  const hit = cache.get(key)
  if (hit) return hit
  const forward = RAW[`${from}|${to}`]
  const back = RAW[`${to}|${from}`]
  const raw = forward ?? back
  if (!raw) throw new Error(`Ei reittiä: ${from} → ${to}`)
  const route: Route = { from, to, nm: raw.nm, canals: raw.canals, path: forward ? raw.path : [...raw.path].reverse() }
  cache.set(key, route)
  return route
}

/** Point at fraction t (0–1) of the way along a route, by distance. */
export function pointAlong(route: Route, t: number): [number, number] {
  const segs = segmentLengths(route)
  const total = segs[segs.length - 1]
  const target = Math.min(1, Math.max(0, t)) * total
  let i = segs.findIndex((s) => s >= target)
  if (i <= 0) i = 1
  const [a, b] = [route.path[i - 1], route.path[i]]
  const segLen = segs[i] - segs[i - 1] || 1
  const f = (target - segs[i - 1]) / segLen
  let dLon = b[0] - a[0]
  if (dLon > 180) dLon -= 360
  if (dLon < -180) dLon += 360
  let lon = a[0] + dLon * f
  if (lon > 180) lon -= 360
  if (lon < -180) lon += 360
  return [lon, a[1] + (b[1] - a[1]) * f]
}

/** The rest of the route from fraction t onwards (for drawing). */
export function remainingPath(route: Route, t: number): [number, number][] {
  const segs = segmentLengths(route)
  const target = Math.min(1, Math.max(0, t)) * segs[segs.length - 1]
  const i = Math.max(1, segs.findIndex((s) => s >= target))
  return [pointAlong(route, t), ...route.path.slice(i)]
}

const segCache = new WeakMap<Route, number[]>()
function segmentLengths(route: Route): number[] {
  let s = segCache.get(route)
  if (s) return s
  s = [0]
  for (let i = 1; i < route.path.length; i++) {
    const [a, b] = [route.path[i - 1], route.path[i]]
    let dLon = Math.abs(b[0] - a[0])
    if (dLon > 180) dLon = 360 - dLon
    const midLat = ((a[1] + b[1]) / 2) * (Math.PI / 180)
    s.push(s[i - 1] + Math.hypot(dLon * Math.cos(midLat), b[1] - a[1]))
  }
  segCache.set(route, s)
  return s
}
